const subtotal=()=>state.cart.reduce((n,x)=>n+x.price*x.quantity,0);
const header=()=>`<div class="topbar"><div class="topbits"><span>🚚 Free Shipping on Orders Over ৳999</span><span>◆ Secure Payment</span><span>☏ 24/7 Support</span></div><span>Follow Us:　●　▶　◎　♪</span></div><nav class="navbar"><button class="iconbtn mobile-menu" onclick="go('shop')">☰</button><a class="brand" href="#home" style="text-decoration:none;color:var(--text)">${state.storeSettings.logo?`<img src="${esc(state.storeSettings.logo)}" alt="logo" style="max-width:130px;max-height:48px;object-fit:contain">`:`<span class="brandmark">♧</span> ${esc(state.storeSettings.storeName||"SMART OUTFIT")}<small>${esc(state.storeSettings.tagline||"DRESS SMART • LIVE BETTER")}</small>`}</a><div class="navlinks"><a href="#home">⌂ Home</a><a href="#shop">Shop⌄</a><a href="#shop">Men⌄</a><a href="#shop">Women⌄</a><a href="#about">About</a><a href="#blog">Blog</a><a href="#contact">Contact</a>${state.user?.role==="admin"?'<a href="#admin">Admin</a>':""}</div><div class="nav-actions"><input class="search" placeholder="Search products..." value="${state.query}" onkeydown="if(event.key==='Enter'){state.query=this.value;go('shop')}"><button class="theme-toggle" onclick="toggleTheme()" title="Toggle theme">◐</button><button class="iconbtn" onclick="go('account')">♙</button><button class="iconbtn" onclick="go('wishlist')">♡<i class="count">${state.wish.length}</i></button><button class="iconbtn" onclick="go('cart')">🛒<i class="count">${cartCount()}</i></button></div></nav>`;
const footer=()=>`<footer class="footer"><div><div class="brand" style="color:white">${state.storeSettings.logo?`<img src="${esc(state.storeSettings.logo)}" alt="logo" style="max-width:130px;max-height:48px;object-fit:contain">`:esc(state.storeSettings.storeName||"SMART OUTFIT")}<small>${esc(state.storeSettings.tagline||"DRESS SMART • LIVE BETTER")}</small></div><p style="color:#bbb;font-size:13px">${esc(state.storeSettings.footerText||"Upgrade your style with quality fashion. Trendy. Comfortable. Always You.")}</p>${state.storeSettings.contactPhone?`<p style="color:#bbb;font-size:13px">Phone: ${esc(state.storeSettings.contactPhone)}</p>`:""}${state.storeSettings.contactEmail?`<p style="color:#bbb;font-size:13px">Email: ${esc(state.storeSettings.contactEmail)}</p>`:""}</div><div><b>Quick Links</b><a href="#home">Home</a><a href="#shop">Shop</a><a href="#about">About</a><a href="#contact">Contact</a>${state.user?.role==="admin"?'<a href="#admin">Admin</a>':""}</div><div><b>Customer Care</b><a href="#faq">FAQs</a><a href="#shipping">Shipping Policy</a><a href="#returns">Return Policy</a><a href="#privacy">Privacy Policy</a></div><div><b>Follow Us</b><p>●　▶　◎　♪</p><b>Subscribe to Our Newsletter</b><p style="font-size:12px;color:#bbb">Get the latest updates, discounts & more.</p><form onsubmit="event.preventDefault();toast('Thanks for subscribing!')"><input placeholder="Your email address" required style="padding:10px;border-radius:8px;width:65%"><button class="btn">Join</button></form></div></footer><div class="copyright"><span>© 2026 ${esc(state.storeSettings.storeName||"SMART OUTFIT")}. All Rights Reserved.</span><span>Made with ❤️ in Bangladesh</span></div>`;
const banner=(title,sub)=>`<section class="page-banner"><h1>${title}</h1><div>${sub||"Dress Smart • Live Better"}</div></section>`;
function card(p){return `<article class="product-card"><div class="product-image" onclick="go('product/${p.id}')"><img src="${p.image}" alt="${p.name}" loading="lazy"><span class="sale">-${p.discount}%</span><button class="heart" onclick="event.stopPropagation();toggleWish('${p.id}')">${state.wish.includes(p.id)?"♥":"♡"}</button></div><div class="product-info"><h3>${p.name}</h3><div class="price">${money(p.price)} <span class="old">${money(p.oldPrice)}</span></div><div class="rating"><span class="stars">★★★★★</span> ${p.rating} (${p.reviews.toLocaleString()})</div><button class="btn primary" onclick="quickAdd('${p.id}')">🛒 Add to Cart</button></div></article>`}
