   <div class="home-slide-controls">${state.storeBanners.length>1?`<button aria-label="Previous banner" onclick="changeStoreBanner(-1)">←</button><span>${String(state.bannerIndex+1).padStart(2,"0")} <i>/</i> ${String(state.storeBanners.length).padStart(2,"0")}</span><button aria-label="Next banner" onclick="changeStoreBanner(1)">→</button>`:`<span>01 <i>/</i> 01</span>`}</div>
