function shop(){let list=state.products.filter(p=>(!state.query||(p.name+" "+p.category).toLowerCase().includes(state.query.toLowerCase()))&&(!state.category||p.category===state.category));if(state.sort==="price-low")list.sort((a,b)=>a.price-b.price);if(state.sort==="price-high")list.sort((a,b)=>b.price-a.price);return `${banner("Shop Our Collection","Trendy. Comfortable. Always You.")}<main class="content"><div class="shop-layout"><aside class="filters"><h3>⚑ Filter Products</h3><hr><b>Categories</b>${["Men's Fashion","Women's Fashion","Bottom Wear","Footwear","Accessories"].map(c=>`<label><input type="radio" name="cat" ${state.category===c?"checked":""} onchange="state.category='${c}';render()"> ${c}</label>`).join("")}<label><input type="radio" name="cat" ${!state.category?"checked":""} onchange="state.category='';render()"> All Categories</label><hr><b>Price Range</b><p>৳0 – ৳5000</p><button class="btn primary" onclick="state.category='';state.query='';render()">Clear Filters</button></aside><div><div class="toolbar"><span>Showing ${list.length} products</span><select onchange="state.sort=this.value;render()"><option value="default">Default Sorting</option><option value="price-low" ${state.sort==="price-low"?"selected":""}>Price: Low to High</option><option value="price-high" ${state.sort==="price-high"?"selected":""}>Price: High to Low</option></select></div><div class="product-grid">${list.length?list.map(card).join(""):'<div class="empty">No products found. Try another search.</div>'}</div></div></div></main>`}
function product(id){let p=state.products.find(x=>x.id===id)||state.products.find(x=>String(x._id)===id)||state.products[0];if(!p)return `${banner("Product unavailable")}<main class="content"><button class="btn primary" onclick="go('shop')">Back to Shop</button></main>`;let imgs=(p.images&&p.images.length?p.images:[p.image]).filter(Boolean);return `${banner("Product Details","Home　›　Shop　›　"+p.name)}<main class="content"><div class="detail product-detail"><div class="product-gallery"><div class="gallery-thumbs">${imgs.map((im,i)=>`<button class="gallery-thumb ${i===0?"active":""}" onclick="document.getElementById('main-product-image').src='${im}';document.querySelectorAll('.gallery-thumb').forEach(x=>x.classList.remove('active'));this.classList.add('active')"><img src="${im}" alt="${p.name} view ${i+1}"></button>`).join("")}</div><img id="main-product-image" class="main-product-image" src="${imgs[0]||""}" alt="${p.name}"></div><div><h1>${p.name}</h1><div class="rating"><span class="stars">★★★★★</span> ${p.rating||0} (${(p.reviews||0).toLocaleString()} Reviews)</div><h2>${money(p.price)} <span class="old">${money(p.oldPrice)}</span> <small style="color:var(--accent)">Save ${money((p.oldPrice||0)-p.price)} (${p.discount||0}%)</small></h2><p>${p.description||p.shortDescription||""}</p><hr><div class="option"><b>Size:</b>${(p.sizes||[]).map(v=>`<button class="${state.selectedSize===v?"active":""}" onclick="state.selectedSize='${v}';render()">${v}</button>`).join("")}</div><div class="option"><b>Color:</b>${(p.colors||[]).map(v=>`<button class="${state.selectedColor===v?"active":""}" onclick="state.selectedColor='${v}';render()">${v}</button>`).join("")}</div><div class="option"><div class="qty"><button onclick="state.qty=Math.max(1,state.qty-1);render()">−</button><span>${state.qty}</span><button onclick="state.qty++;render()">+</button></div><button class="btn primary" onclick="addToCart('${p.id}',state.qty,state.selectedSize,state.selectedColor)">🛒 Add to Cart</button><button class="btn" onclick="toggleWish('${p.id}')">♡</button></div><button class="btn" style="width:100%" onclick="addToCart('${p.id}',state.qty,state.selectedSize,state.selectedColor);go('checkout')">⚡ Buy Now</button><p>🛡 100% Secure Payment　🚚 Free Shipping　↩ Easy Return</p></div></div><section class="section"><h2 class="section-title">Related Products</h2><div class="product-grid">${state.products.filter(x=>x.id!==p.id).slice(0,4).map(card).join("")}</div></section></main>`}

function summary(){let sub=subtotal(),discount=state.cart.reduce((n,x)=>n+(x.oldPrice-x.price)*x.quantity,0),ship=sub>=999||sub===0?0:60;return `<div class="panel"><h2>🛒 Order Summary</h2><div class="summary-line"><span>Subtotal</span><b>${money(sub)}</b></div><div class="summary-line"><span>Discount</span><b style="color:var(--green)">-${money(discount)}</b></div><div class="summary-line"><span>Shipping</span><b>${money(ship)}</b></div><div class="summary-line total"><span>Total</span><span>${money(sub+ship)}</span></div></div>`}
function cart(){return `${banner("Shopping Cart","Review your items and proceed to checkout.")}<main class="content"><div class="cart-layout"><div class="panel"><h2>🛒 Your Cart (${cartCount()})</h2>${state.cart.length?state.cart.map((x,i)=>`<div class="cart-row"><img src="${x.image}"><div><b>${x.name}</b><p>Size: ${x.size}　|　Color: ${x.color}</p><b>${money(x.price)}</b><div class="qty"><button onclick="changeQty(${i},-1)">−</button><span>${x.quantity}</span><button onclick="changeQty(${i},1)">+</button></div></div><div class="cart-actions"><b>${money(x.price*x.quantity)}</b><button class="btn" onclick="removeCart(${i})">Remove</button></div></div>`).join(""):`<div class="empty"><h2>Your cart is empty</h2><button class="btn primary" onclick="go('shop')">Continue Shopping</button></div>`}<div style="display:flex;justify-content:space-between;margin-top:18px"><button class="btn" onclick="state.cart=[];save();render()">Clear Cart</button><button class="btn" onclick="go('shop')">← Continue Shopping</button></div></div><div>${summary()}<button class="btn primary" style="width:100%;margin-top:14px" ${!state.cart.length?"disabled":""} onclick="go('checkout')">🔒 Proceed to Checkout →</button><p class="panel">🛡 100% Secure Checkout<br><small>Your information is safe with us.</small></p></div></div></main>`}
function checkout(){if(!state.cart.length)return `${banner("Checkout")}<main class="content"><div class="empty">Your cart is empty. <button class="btn primary" onclick="go('shop')">Shop now</button></div></main>`;if(!state.user)return `${banner("Checkout","Please log in to complete your order.")}<main class="content"><div class="empty"><button class="btn primary" onclick="go('login')">Login to continue</button></div></main>`;return `${banner("Checkout","Complete your order quickly and securely.")}<main class="content"><div class="cart-layout"><form class="panel" onsubmit="placeOrder(event)"><h2>♙ Billing Information</h2><div class="form-grid"><label class="field">Full Name *<input name="name" required value="${state.user.name||""}"></label><label class="field">Email Address *<input name="email" type="email" required value="${state.user.email||""}"></label><label class="field">Phone Number *<input name="phone" required value="${state.user.phone||""}"></label><label class="field">City<input name="city" value="Dhaka"></label></div><label class="field">Shipping Address *<input name="address" required placeholder="House, road, area"></label><h3>Coupon Code</h3><div style="display:flex;gap:8px;margin:10px 0"><input id="checkout-coupon" placeholder="Enter coupon code" style="flex:1;padding:12px;border:1px solid #ddd;border-radius:8px"><button type="button" class="btn" onclick="applyCheckoutCoupon()">Apply</button></div><small id="coupon-result">${state.activeCoupon?`Applied ${esc(state.activeCoupon)} · Discount ${money(state.couponDiscount)}`:""}</small><h3>▣ Payment Method</h3><label><input type="radio" name="paymentMethod" value="cod" checked> Cash on Delivery</label><p><label><input type="radio" name="paymentMethod" value="online"> Online Payment (gateway integration required)</label></p><button class="btn primary" style="width:100%;margin-top:15px">✓ Place Order →</button></form><div>${summary()}</div></div></main>`}
function wishlist(){let items=state.products.filter(p=>state.wish.includes(p.id));return `${banner("My Wishlist","Save your favorite products for later.")}<main class="content"><div class="panel"><h2>♥ My Wishlist (${items.length}) <button class="btn" style="float:right" onclick="state.wish=[];save();render()">Clear Wishlist</button></h2><div class="product-grid">${items.length?items.map(card).join(""):'<div class="empty">Your wishlist is empty.</div>'}</div></div></main>`}
function login(){return `${banner("Login / Register","Login to your account or create a new account.")}<main class="content"><div class="auth-wrap"><form class="panel" onsubmit="authSubmit(event,'login')"><h2>Welcome Back!</h2><p>Login to your account</p><input name="email" type="email" placeholder="Email Address" required><input name="password" type="password" placeholder="Password" required><button class="btn primary" style="width:100%">Login</button><p>New here? <a href="#register">Create account</a></p></form><form class="panel" onsubmit="authSubmit(event,'register')"><h2>Create Account</h2><p>Join Smart Outfit today</p><input name="name" placeholder="Full Name" required><input name="email" type="email" placeholder="Email Address" required><input name="phone" placeholder="Phone Number"><input name="password" type="password" placeholder="Password (6+ characters)" minlength="6" required><button class="btn primary" style="width:100%">Register</button></form></div></main>`}
function account(){if(!state.user)return `${banner("My Account","Manage your profile, orders and more.")}<main class="content"><div class="empty"><button class="btn primary" onclick="go('login')">Login / Register</button></div></main>`;return `${banner("My Account","Manage your profile, orders and more.")}<main class="content"><div class="panel"><h2>Welcome, ${state.user.name}</h2><p>${state.user.email}</p><button class="btn" onclick="logout()">Logout</button><h3>Recent Orders</h3><div id="orders">Loading orders…</div></div></main>`}

function admin(){if(!state.user||state.user.role!=="admin")return `${banner("Admin Access","Sign in with your store administrator account.")}<main class="content"><div class="empty"><h2>Administrator sign-in required</h2><p>This area is protected. Only your admin account can manage the store.</p><button class="btn primary" onclick="go('login')">Admin Login</button></div></main>`;
return `${banner("Admin Dashboard","SMART OUTFIT · Store Management")}<main class="content admin-content"><div class="admin-heading"><div><span class="eyebrow-dark">STORE CONTROL CENTER</span><h2>Welcome back, ${state.user.name}</h2><p>Monitor sales, manage customer orders and keep your store running.</p></div><button class="btn primary" onclick="loadAdmin()">↻ Refresh Data</button></div><div class="admin-shell"><aside class="admin-sidebar"><div class="admin-user"><div class="admin-avatar">${(state.user.name||"A").slice(0,1).toUpperCase()}</div><div><b>${state.user.name}</b><small>Store Administrator</small></div></div><a class="active" href="#admin">▦　 Overview</a><a href="#admin" onclick="document.getElementById('admin-products').scrollIntoView({behavior:'smooth'});return false">◈　 Products</a><a href="#admin" onclick="document.getElementById('admin-orders').scrollIntoView({behavior:'smooth'});return false">▣　 Orders</a><a href="#admin" onclick="document.getElementById('admin-customers').scrollIntoView({behavior:'smooth'});return false">♙　 Customers</a><a href="#admin" onclick="adminJump('admin-categories');return false">▤　 Categories</a><a href="#admin" onclick="adminJump('admin-banners');return false">▧　 Banners</a><a href="#admin" onclick="adminJump('admin-settings');return false">⚙　 Branding</a><a href="#admin" onclick="adminJump('admin-coupons');return false">％　 Coupons</a><a href="#admin" onclick="adminJump('admin-support');return false">✉　 Support</a><a href="#admin" onclick="adminJump('admin-delivery');return false">⇄　 Payment & Delivery</a><a href="#shop">◈　 Storefront</a><button onclick="logout()">↪　 Logout</button></aside><section class="admin-main"><div id="admin-stats" class="admin-stats"><div class="admin-stat">Loading dashboard…</div></div><div class="admin-section" id="admin-products"><div class="admin-section-head"><div><h3>Product Management</h3><p>Add, edit, publish and organize your store catalogue.</p></div><button class="btn primary" onclick="openProductEditor()">＋ Add New Product</button></div><div class="product-admin-toolbar"><input id="admin-product-search" placeholder="Search by product, SKU or category…" oninput="filterAdminProducts()"><span id="admin-product-count"></span></div><div id="admin-products-table">Loading products…</div></div><div class="admin-section" id="admin-orders"><div class="admin-section-head"><div><h3>Recent Orders</h3><p>Review customer purchases and update delivery status.</p></div><span class="admin-live">● LIVE DATA</span></div><div id="admin-orders-table">Loading orders…</div></div><div class="admin-section" id="admin-customers"><div class="admin-section-head"><div><h3>Customer Directory</h3><p>Customer accounts registered in your store.</p></div></div><div id="admin-customers-list">Loading customers…</div></div>
<div class="admin-section" id="admin-categories"><div class="admin-section-head"><div><h3>Category Management</h3><p>Create and organize product categories.</p></div><button class="btn primary" onclick="addCategory()">＋ Add Category</button></div><div id="admin-category-list">Loading categories…</div></div>
<div class="admin-section" id="admin-banners"><div class="admin-section-head"><div><h3>Homepage Banner Slider</h3><p>Manage promotional slides shown on the storefront.</p></div><button class="btn primary" onclick="addBanner()">＋ Add Banner</button></div><div id="admin-banner-list">Loading banners…</div></div>
<div class="admin-section" id="admin-settings"><div class="admin-section-head"><div><h3>Website Branding & Store Settings</h3><p>Control logo, theme colors, contact information and footer.</p></div></div><div id="admin-settings-form">Loading settings…</div></div>
<div class="admin-section" id="admin-coupons"><div class="admin-section-head"><div><h3>Coupons & Discounts</h3><p>Create discount codes and manage expiry and usage limits.</p></div><button class="btn primary" onclick="addCoupon()">＋ Create Coupon</button></div><div id="admin-coupon-list">Loading coupons…</div></div>
<div class="admin-section" id="admin-support"><div class="admin-section-head"><div><h3>Customer Support</h3><p>Review customer questions and update ticket status.</p></div></div><div id="admin-ticket-list">Loading tickets…</div></div>
<div class="admin-section" id="admin-delivery"><div class="admin-section-head"><div><h3>Payment Gateway & Delivery</h3><p>Configure COD, gateway credentials and delivery charges.</p></div></div><div id="admin-payment-delivery">Loading configuration…</div></div>
</section></div></main>`}
async function loadAdmin(){
 const headers={Authorization:"Bearer "+state.token};
 try{
  const [sr,orr,cr,pr]=await Promise.all([fetch(API+"/admin/stats",{headers}),fetch(API+"/admin/orders",{headers}),fetch(API+"/admin/customers",{headers}),fetch(API+"/admin/products",{headers})]);
  const [stats,orders,customers,products]=await Promise.all([sr.json(),orr.json(),cr.json(),pr.json()]);
  if(!sr.ok)throw Error(stats.message||"Admin access denied");
  state.adminProducts=Array.isArray(products)?products:[]; renderAdminProducts();
  const statsEl=document.getElementById("admin-stats");
  if(statsEl)statsEl.innerHTML=`<article class="admin-stat"><span>Total Revenue</span><strong>${money(stats.revenue)}</strong><small>Confirmed store sales</small><i>৳</i></article><article class="admin-stat"><span>Total Orders</span><strong>${stats.orders}</strong><small>All customer orders</small><i>▣</i></article><article class="admin-stat"><span>Customers</span><strong>${stats.users}</strong><small>Registered accounts</small><i>♙</i></article><article class="admin-stat"><span>Pending Orders</span><strong>${stats.pending}</strong><small>Need your attention</small><i>◷</i></article><article class="admin-stat"><span>Products</span><strong>${stats.products||0}</strong><small>In your catalogue</small><i>◈</i></article><article class="admin-stat"><span>Low Stock</span><strong>${stats.lowStock||0}</strong><small>5 or fewer remaining</small><i>!</i></article>`;
  const ordersEl=document.getElementById("admin-orders-table");
  if(ordersEl)ordersEl.innerHTML=orders.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ORDER ID</th><th>CUSTOMER</th><th>DATE</th><th>AMOUNT</th><th>PAYMENT</th><th>ORDER STATUS</th><th>DETAILS</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>#${String(o._id).slice(-7).toUpperCase()}</b></td><td><b>${o.shipping?.name||o.user?.name||"Customer"}</b><small>${o.shipping?.phone||o.user?.email||""}</small></td><td>${new Date(o.createdAt).toLocaleDateString()}</td><td><b>${money(o.total)}</b></td><td>${o.paymentMethod==="cod"?"Cash on Delivery":"Online"}</td><td><select class="status-select" aria-label="Update order status" onchange="updateOrder('${o._id}',this.value)">${["Pending","Processing","Shipped","Delivered","Cancelled"].map(x=>`<option ${o.status===x?"selected":""}>${x}</option>`).join("")}</select></td><td><button class="btn" onclick="viewOrder('${o._id}')">View</button> <button class="btn" onclick="downloadInvoice('${o._id}')">Invoice PDF</button></td></tr>`).join("")}</tbody></table></div>`:`<div class="admin-empty">No orders have been placed yet.</div>`;
  const customersEl=document.getElementById("admin-customers-list");
  if(customersEl)customersEl.innerHTML=customers.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CUSTOMER</th><th>EMAIL ADDRESS</th><th>PHONE</th><th>JOINED</th><th>ACCOUNT</th></tr></thead><tbody>${customers.map(c=>`<tr><td><b>${c.name}</b></td><td>${c.email}</td><td>${c.phone||"Not provided"}</td><td>${new Date(c.createdAt).toLocaleDateString()}</td><td><span class="customer-active">● Active</span></td></tr>`).join("")}</tbody></table></div>`:`<div class="admin-empty">No customers registered yet.</div>`;
  loadAdminModules();
 }catch(e){const el=document.getElementById("admin-orders-table");if(el)el.textContent=e.message;toast(e.message)}
}
async function updateOrder(id,status){try{let r=await fetch(API+"/admin/orders/"+id,{method:"PATCH",headers:{"Content-Type":"application/json",Authorization:"Bearer "+state.token},body:JSON.stringify({status})});let x=await r.json();if(!r.ok)throw Error(x.message);toast("Order status updated");loadAdmin()}catch(e){toast(e.message)}}



function adminJump(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
const adminHeaders=()=>({Authorization:'Bearer '+state.token,'Content-Type':'application/json'});
async function adminApi(path,opts={}){let r=await fetch(API+path,{...opts,headers:{...adminHeaders(),...(opts.headers||{})}});let x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.message||'Request failed');return x}
async function loadAdminModules(){try{const [cats,banners,settings,coupons,tickets]=await Promise.all(['/store/categories','/store/banners','/store/settings','/store/coupons','/store/tickets'].map(x=>adminApi(x)));renderCategories(cats);renderBanners(banners);renderStoreSettings(settings);renderCoupons(coupons);renderTickets(tickets);renderPaymentDelivery(settings)}catch(e){toast('Admin modules: '+e.message)}}
function renderCategories(rows){let el=document.getElementById('admin-category-list');if(!el)return;el.innerHTML=rows.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>NAME</th><th>SLUG</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.slug||'')}</td><td>${c.active?'Active':'Hidden'}</td><td><button class="btn" onclick="editCategory('${c._id}','${esc(c.name)}',${!!c.active})">Edit</button> <button class="btn danger" onclick="deleteStoreItem('categories','${c._id}')">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty">No categories yet.</div>'}
async function addCategory(){let name=prompt('Category name?');if(!name)return;let image=prompt('Category image URL (optional):')||'';try{await adminApi('/store/categories',{method:'POST',body:JSON.stringify({name,image})});toast('Category created');loadAdminModules()}catch(e){toast(e.message)}}
async function editCategory(id,name,active){let n=prompt('Category name:',name);if(n===null)return;let image=prompt('Category image URL (optional):')||'';try{await adminApi('/store/categories/'+id,{method:'PUT',body:JSON.stringify({name:n,image,active})});loadAdminModules()}catch(e){toast(e.message)}}
function renderBanners(rows){let el=document.getElementById('admin-banner-list');if(!el)return;el.innerHTML=rows.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>PREVIEW</th><th>TITLE</th><th>LINK</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(b=>`<tr><td><img src="${esc(b.image)}" style="width:90px;height:48px;object-fit:cover;border-radius:6px"></td><td>${esc(b.title||'Untitled')}</td><td>${esc(b.link||'#shop')}</td><td>${b.active?'Active':'Hidden'}</td><td><button class="btn" onclick="editBanner('${b._id}')">Edit</button> <button class="btn danger" onclick="deleteStoreItem('banners','${b._id}')">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty">No homepage banners created yet.</div>'}
async function addBanner(){let title=prompt('Banner title:');if(title===null)return;let image=prompt('Banner image URL (or uploaded image path):');if(!image)return;try{await adminApi('/store/banners',{method:'POST',body:JSON.stringify({title,image,subtitle:prompt('Subtitle:')||'',buttonText:'Shop Now',link:'#shop',active:true})});toast('Banner added');loadAdminModules()}catch(e){toast(e.message)}}
async function editBanner(id){let rows=await adminApi('/store/banners');let b=rows.find(x=>x._id===id);if(!b)return;let title=prompt('Banner title:',b.title||'');if(title===null)return;let image=prompt('Image URL:',b.image);if(!image)return;try{await adminApi('/store/banners/'+id,{method:'PUT',body:JSON.stringify({...b,title,image})});loadAdminModules()}catch(e){toast(e.message)}}
async function deleteStoreItem(type,id){if(!confirm('Delete this item?'))return;try{await adminApi('/store/'+type+'/'+id,{method:'DELETE'});toast('Deleted');loadAdminModules()}catch(e){toast(e.message)}}
function renderStoreSettings(s){let el=document.getElementById('admin-settings-form');if(!el)return;el.innerHTML=`<form class="editor-grid" onsubmit="saveStoreSettings(event)"><label>Store name<input name="storeName" value="${esc(s.storeName||'SMART OUTFIT')}"></label><label>Logo image URL<input name="logo" value="${esc(s.logo||'')}"></label><label>Tagline<input name="tagline" value="${esc(s.tagline||'')}"></label><label>Primary color<input name="primaryColor" type="color" value="${esc(s.primaryColor||'#111111')}"></label><label>Accent color<input name="accentColor" type="color" value="${esc(s.accentColor||'#c9a96e')}"></label><label>Contact email<input name="contactEmail" value="${esc(s.contactEmail||'')}"></label><label>Contact phone<input name="contactPhone" value="${esc(s.contactPhone||'')}"></label><label>Address<input name="address" value="${esc(s.address||'')}"></label><label class="wide">Footer text<textarea name="footerText">${esc(s.footerText||'')}</textarea></label><div class="wide"><button class="btn primary">Save Website Settings</button></div></form>`}
async function saveStoreSettings(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await adminApi('/store/settings',{method:'PUT',body:JSON.stringify(d)});toast('Website settings saved');}catch(e){toast(e.message)}}
function renderCoupons(rows){let el=document.getElementById('admin-coupon-list');if(!el)return;el.innerHTML=rows.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CODE</th><th>DISCOUNT</th><th>MIN ORDER</th><th>USED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>${c.type==='percent'?c.value+'%':money(c.value)}</td><td>${money(c.minOrder)}</td><td>${c.usedCount||0}/${c.usageLimit||'∞'}</td><td>${c.active?'Active':'Inactive'}</td><td><button class="btn danger" onclick="deleteStoreItem('coupons','${c._id}')">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty">No coupons created yet.</div>'}
async function addCoupon(){let code=prompt('Coupon code:');if(!code)return;let value=Number(prompt('Discount value (percent or amount):','10'));if(!value||value<0)return;let type=confirm('OK = percentage discount; Cancel = fixed BDT discount')?'percent':'fixed';let minOrder=Number(prompt('Minimum order amount (BDT):','0')||0);let usageLimit=Number(prompt('Maximum uses (0 = unlimited):','0')||0);let maxDiscount=type==='percent'?Number(prompt('Maximum discount cap (0 = no cap):','0')||0):0;try{await adminApi('/store/coupons',{method:'POST',body:JSON.stringify({code,value,type,active:true,minOrder,usageLimit,maxDiscount})});toast('Coupon created');loadAdminModules()}catch(e){toast(e.message)}}
function renderTickets(rows){let el=document.getElementById('admin-ticket-list');if(!el)return;el.innerHTML=rows.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CUSTOMER</th><th>SUBJECT / MESSAGE</th><th>DATE</th><th>STATUS</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc(t.name)}<small>${esc(t.email||'')} ${esc(t.phone||'')}</small></td><td><b>${esc(t.subject||'Support')}</b><small>${esc(t.message||'')}</small></td><td>${new Date(t.createdAt).toLocaleDateString()}</td><td><select class="status-select" onchange="updateTicket('${t._id}',this.value)">${['Open','In Progress','Resolved'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty">No support tickets received.</div>'}
async function updateTicket(id,status){try{await adminApi('/store/tickets/'+id,{method:'PATCH',body:JSON.stringify({status})});toast('Ticket updated')}catch(e){toast(e.message)}}
function renderPaymentDelivery(s){let el=document.getElementById('admin-payment-delivery');if(!el)return;let p=s.payment||{},d=s.delivery||{};el.innerHTML=`<form class="editor-grid" onsubmit="savePaymentDelivery(event)"><h4 class="wide">Payment methods</h4><label class="check-field"><input type="checkbox" name="cod" ${p.cod!==false?'checked':''}> Enable Cash on Delivery</label><label class="check-field"><input type="checkbox" name="sslcommerz" ${p.sslcommerz?'checked':''}> Enable SSLCommerz (requires merchant credentials)</label><label>Gateway provider<select name="provider"><option value="sslcommerz" ${p.provider==='sslcommerz'?'selected':''}>SSLCommerz</option><option value="aamarpay" ${p.provider==='aamarpay'?'selected':''}>aamarPay</option></select></label><label>Merchant Store ID<input name="storeId" value="${esc(p.storeId||'')}"></label><label>Merchant Password / API Key<input name="storePassword" type="password" placeholder="Leave blank to keep existing"></label><p class="wide" style="color:#a66">Gateway credentials are stored for configuration. Live payment processing still requires provider account approval, callback URLs and server-side integration.</p><h4 class="wide">Delivery management</h4><label>Inside Dhaka delivery (৳)<input name="insideDhaka" type="number" value="${Number(d.insideDhaka??60)}"></label><label>Outside Dhaka delivery (৳)<input name="outsideDhaka" type="number" value="${Number(d.outsideDhaka??120)}"></label><label>Free delivery above (৳)<input name="freeShippingOver" type="number" value="${Number(d.freeShippingOver??999)}"></label><label>Courier service<input name="courier" value="${esc(d.courier||'')}"></label><label>Courier API key<input name="apiKey" type="password" placeholder="Leave blank to keep existing"></label><div class="wide"><button class="btn primary">Save Payment & Delivery Settings</button></div></form>`}
async function savePaymentDelivery(e){e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));let old=await adminApi('/store/settings');let payment={...(old.payment||{}),cod:f.elements.cod.checked,sslcommerz:f.elements.sslcommerz.checked,provider:d.provider,storeId:d.storeId};if(d.storePassword)payment.storePassword=d.storePassword;let delivery={...(old.delivery||{}),insideDhaka:Number(d.insideDhaka),outsideDhaka:Number(d.outsideDhaka),freeShippingOver:Number(d.freeShippingOver),courier:d.courier};if(d.apiKey)delivery.apiKey=d.apiKey;try{await adminApi('/store/settings',{method:'PUT',body:JSON.stringify({payment,delivery})});toast('Payment & delivery configuration saved')}catch(e){toast(e.message)}}
async function viewOrder(id){try{let o=await adminApi('/admin/orders/'+id);alert(`ORDER #${id.slice(-7).toUpperCase()}\nCustomer: ${o.shipping?.name||o.user?.name}\nPhone: ${o.shipping?.phone||''}\nAddress: ${o.shipping?.address||''}, ${o.shipping?.city||''}\nItems: ${(o.items||[]).map(i=>i.name+' × '+i.quantity).join(', ')}\nTotal: ${money(o.total)}\nPayment: ${o.paymentMethod}\nStatus: ${o.status}`)}catch(e){toast(e.message)}}
async function downloadInvoice(id){try{const r=await fetch(API+'/admin/orders/'+id+'/invoice',{headers:{Authorization:'Bearer '+state.token}});if(!r.ok){let x=await r.json().catch(()=>({}));throw Error(x.message||'Invoice download failed')}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='SMART-OUTFIT-invoice-'+id.slice(-7)+'.pdf';a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message)}}

state.adminProducts=[]; state.editingProduct=null;
function renderAdminProducts(){const el=document.getElementById("admin-products-table");if(!el)return;const q=(document.getElementById("admin-product-search")?.value||"").toLowerCase();const rows=state.adminProducts.filter(p=>(p.name+" "+(p.sku||"")+" "+p.category).toLowerCase().includes(q));const count=document.getElementById("admin-product-count");if(count)count.textContent=`${rows.length} of ${state.adminProducts.length} products`;el.innerHTML=rows.length?`<div class="admin-table-wrap"><table class="admin-table product-admin-table"><thead><tr><th>PRODUCT</th><th>SKU / CATEGORY</th><th>PRICE</th><th>STOCK</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="admin-product-cell"><img src="${p.image||p.images?.[0]||""}" alt=""><b>${p.name}</b></div></td><td>${p.sku||"—"}<small>${p.category}</small></td><td><b>${money(p.price)}</b><small>${p.oldPrice?money(p.oldPrice):"No compare price"}</small></td><td><span class="${p.stock<=5?"stock-low":"stock-ok"}">${p.stock??0} units</span></td><td><span class="product-status">${p.status||"Active"}</span></td><td><div class="product-actions"><button class="btn" onclick="openProductEditor('${p._id}')">Edit</button><button class="btn" onclick="duplicateProduct('${p._id}')">Duplicate</button><button class="btn danger" onclick="deleteProduct('${p._id}')">Delete</button></div></td></tr>`).join("")}</tbody></table></div>`:`<div class="admin-empty">No products found. Add your first product to get started.</div>`;}
function filterAdminProducts(){renderAdminProducts()}
function openProductEditor(id){const p=id?state.adminProducts.find(x=>x._id===id):null;state.editingProduct=p||null;const values=p||{name:"",sku:"",category:"Men's Fashion",price:"",oldPrice:"",discount:0,stock:0,status:"Active",description:"",shortDescription:"",sizes:["S","M","L","XL"],colors:["Black","White"],images:[],featured:false};const modal=document.createElement("div");modal.className="product-modal-backdrop";modal.id="product-editor-modal";modal.innerHTML=`<section class="product-editor"><header><div><span class="eyebrow-dark">CATALOGUE MANAGEMENT</span><h2>${p?"Edit Product":"Create Product"}</h2><p>Control product details, variants, pricing and gallery images.</p></div><button class="iconbtn" onclick="closeProductEditor()">✕</button></header><form id="product-editor-form" onsubmit="saveProduct(event,'${p? p._id:""}')"><div class="editor-grid"><label>Product name *<input name="name" required maxlength="140" value="${esc(values.name)}"></label><label>SKU<input name="sku" value="${esc(values.sku||"")}" placeholder="e.g. SO-HOOD-001"></label><label>Category *<select name="category" required>${(state.storeCategories.length?state.storeCategories.map(c=>c.name):[values.category||"Uncategorized"]).map(c=>`<option value="${esc(c)}" ${c===values.category?"selected":""}>${esc(c)}</option>`).join("")}</select></label><label>Price (৳) *<input name="price" type="number" min="0" required value="${values.price}"></label><label>Compare at price (৳)<input name="oldPrice" type="number" min="0" value="${values.oldPrice||0}"></label><label>Discount (%)<input name="discount" type="number" min="0" max="95" value="${values.discount||0}"></label><label>Available stock<input name="stock" type="number" min="0" value="${values.stock??0}"></label><label>Status<select name="status"><option ${values.status==="Active"?"selected":""}>Active</option><option ${values.status==="Draft"?"selected":""}>Draft</option><option ${values.status==="Archived"?"selected":""}>Archived</option></select></label><label class="wide">Short description<input name="shortDescription" maxlength="300" value="${esc(values.shortDescription||"")}"></label><label class="wide">Full description<textarea name="description" rows="4">${esc(values.description||"")}</textarea></label><label>Sizes <small>Separate with commas</small><input name="sizes" value="${esc((values.sizes||[]).join(", "))}" placeholder="S, M, L, XL, XXL"></label><label>Colors <small>Separate with commas</small><input name="colors" value="${esc((values.colors||[]).join(", "))}" placeholder="Black, White, Grey"></label><label class="wide">Product image gallery <small>Upload multiple images (JPG, PNG, WEBP · max 5MB each)</small><input id="product-image-files" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple><div id="product-image-preview" class="image-preview-grid">${(values.images||[]).map((im,i)=>`<div class="image-preview"><img src="${im}"><button type="button" onclick="removeEditorImage(${i})">×</button></div>`).join("")}</div></label><label class="check-field"><input name="featured" type="checkbox" ${values.featured?"checked":""}> Feature this product on homepage</label></div><footer><button type="button" class="btn" onclick="closeProductEditor()">Cancel</button><button class="btn primary" id="save-product-button">${p?"Save Changes":"Create Product"}</button></footer></form></section>`;document.body.appendChild(modal);modal.dataset.images=JSON.stringify(values.images||[]);document.getElementById("product-image-files").addEventListener("change",previewProductImages);}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function closeProductEditor(){document.getElementById("product-editor-modal")?.remove()}
function currentEditorImages(){try{return JSON.parse(document.getElementById("product-editor-modal").dataset.images||"[]")}catch(e){return []}}
function setEditorImages(a){const m=document.getElementById("product-editor-modal");m.dataset.images=JSON.stringify(a);document.getElementById("product-image-preview").innerHTML=a.map((im,i)=>`<div class="image-preview"><img src="${im}"><button type="button" onclick="removeEditorImage(${i})">×</button></div>`).join("")}
function removeEditorImage(i){const a=currentEditorImages();a.splice(i,1);setEditorImages(a)}
async function previewProductImages(e){const files=[...e.target.files];if(!files.length)return;const fd=new FormData();files.forEach(f=>fd.append("images",f));const btn=document.getElementById("save-product-button");btn.disabled=true;btn.textContent="Uploading images…";try{const r=await fetch(API+"/admin/uploads",{method:"POST",headers:{Authorization:"Bearer "+state.token},body:fd});const out=await r.json();if(!r.ok)throw Error(out.message);setEditorImages([...currentEditorImages(),...out.images]);toast(`${out.images.length} image(s) uploaded`)}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent=state.editingProduct?"Save Changes":"Create Product";e.target.value=""}}
async function saveProduct(e,id){e.preventDefault();const form=e.target,fd=new FormData(form),v=Object.fromEntries(fd);const payload={name:v.name,sku:v.sku,category:v.category,price:Number(v.price),oldPrice:Number(v.oldPrice||0),discount:Number(v.discount||0),stock:Number(v.stock||0),status:v.status,shortDescription:v.shortDescription,description:v.description,sizes:v.sizes.split(",").map(x=>x.trim()).filter(Boolean),colors:v.colors.split(",").map(x=>x.trim()).filter(Boolean),images:currentEditorImages(),featured:fd.has("featured")};payload.image=payload.images[0]||"";const btn=document.getElementById("save-product-button");btn.disabled=true;btn.textContent="Saving…";try{const r=await fetch(API+"/admin/products"+(id?"/"+id:""),{method:id?"PUT":"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+state.token},body:JSON.stringify(payload)});const out=await r.json();if(!r.ok)throw Error(out.message||"Could not save product");toast(id?"Product updated successfully":"Product created successfully");closeProductEditor();await loadProducts();await loadAdmin()}catch(err){toast(err.message);btn.disabled=false;btn.textContent=id?"Save Changes":"Create Product"}}
async function deleteProduct(id){const p=state.adminProducts.find(x=>x._id===id);if(!p||!confirm(`Delete “${p.name}”? This cannot be undone.`))return;try{const r=await fetch(API+"/admin/products/"+id,{method:"DELETE",headers:{Authorization:"Bearer "+state.token}});const out=await r.json();if(!r.ok)throw Error(out.message);toast("Product deleted");await loadProducts();await loadAdmin()}catch(e){toast(e.message)}}
function duplicateProduct(id){const p=state.adminProducts.find(x=>x._id===id);if(!p)return;openProductEditor();const f=document.getElementById("product-editor-form");for(const [k,v] of Object.entries({name:p.name+" (Copy)",sku:"",category:p.category,price:p.price,oldPrice:p.oldPrice,discount:p.discount,stock:p.stock,status:"Draft",shortDescription:p.shortDescription,description:p.description,sizes:(p.sizes||[]).join(", "),colors:(p.colors||[]).join(", ")})){if(f.elements[k])f.elements[k].value=v;}setEditorImages(p.images||[p.image]);}

function render(){let route=decodeURIComponent(location.hash.slice(1)||"home"),parts=route.split("/");let view=parts[0];let html=view==="home"?home():view==="shop"?shop():view==="product"?product(parts[1]):view==="cart"?cart():view==="checkout"?checkout():view==="wishlist"?wishlist():view==="login"||view==="register"?login():view==="account"?account():view==="admin"?admin():`${banner("Page not found")}<main class="content"><button class="btn primary" onclick="go('home')">Go Home</button></main>`;document.getElementById("app").innerHTML=header()+html+footer();if(view==="account"&&state.user)loadOrders();if(view==="admin"&&state.user?.role==="admin")loadAdmin();}
async function submitSupport(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const r=await fetch(API+'/store/support',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const x=await r.json();if(!r.ok)throw Error(x.message);toast(x.message);e.target.reset()}catch(e){toast(e.message)}}
function changeStoreBanner(delta){if(!state.storeBanners.length)return;state.bannerIndex=(state.bannerIndex+delta+state.storeBanners.length)%state.storeBanners.length;render()}
async function loadStorefront(){try{const r=await fetch(API+'/store/public');if(r.ok){const x=await r.json();state.storeSettings=x.settings||{};state.storeBanners=x.banners||[];state.bannerIndex=0;state.storeCategories=x.categories||[];if(state.storeSettings.primaryColor)document.documentElement.style.setProperty('--black',state.storeSettings.primaryColor);if(state.storeSettings.accentColor)document.documentElement.style.setProperty('--accent',state.storeSettings.accentColor);render()}}catch(e){}}
async function loadProducts(){try{let r=await fetch(API+"/products");if(r.ok)state.products=await r.json()}catch(e){}render()}
function addToCart(id,qty=1,size="L",color="Black"){let p=state.products.find(x=>x.id===id);if(!p)return;let found=state.cart.find(x=>x.id===id&&x.size===size&&x.color===color);if(found)found.quantity+=qty;else state.cart.push({...p,quantity:qty,size,color});save();toast("Added to cart");render()}
function quickAdd(id){let p=state.products.find(x=>x.id===id);addToCart(id,1,p.sizes[0],p.color)}
function toggleWish(id){state.wish=state.wish.includes(id)?state.wish.filter(x=>x!==id):[...state.wish,id];save();toast(state.wish.includes(id)?"Added to wishlist":"Removed from wishlist");render()}
function changeQty(i,d){state.cart[i].quantity=Math.max(1,state.cart[i].quantity+d);save();render()}
function removeCart(i){state.cart.splice(i,1);save();render();toast("Item removed")}
function toggleTheme(){let dark=document.documentElement.dataset.theme!=="dark";document.documentElement.dataset.theme=dark?"dark":"light";localStorage.theme=dark?"dark":"light"}
async function authSubmit(e,type){e.preventDefault();let data=Object.fromEntries(new FormData(e.target));try{let r=await fetch(API+"/auth/"+type,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});let out=await r.json();if(!r.ok)throw Error(out.message||"Authentication failed");state.token=out.token;state.user=out.user;localStorage.token=out.token;localStorage.user=JSON.stringify(out.user);toast("Welcome, "+out.user.name);go("account")}catch(err){toast(err.message+" (Make sure MongoDB is running)")}}
function logout(){state.user=null;state.token="";localStorage.removeItem("user");localStorage.removeItem("token");toast("Logged out");go("home")}
async function applyCheckoutCoupon(){const code=document.getElementById('checkout-coupon')?.value?.trim();if(!code)return toast('Enter a coupon code');try{const r=await fetch(API+'/store/coupon/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code,subtotal:subtotal()})});const x=await r.json();if(!r.ok)throw Error(x.message);state.activeCoupon=x.code;state.couponDiscount=x.discount;const el=document.getElementById('coupon-result');if(el)el.textContent=`Coupon ${x.code} applied. Discount: ${money(x.discount)}`;toast('Coupon applied')}catch(e){state.activeCoupon=null;state.couponDiscount=0;const el=document.getElementById('coupon-result');if(el)el.textContent=e.message;toast(e.message)}}
async function placeOrder(e){e.preventDefault();let form=Object.fromEntries(new FormData(e.target));let sub=subtotal(),discount=state.couponDiscount||0,shippingCharge=sub>=999?0:60;let body={couponCode:state.activeCoupon,items:state.cart.map(x=>({productId:x.id,name:x.name,image:x.image,price:x.price,quantity:x.quantity,size:x.size,color:x.color})),shipping:form,paymentMethod:form.paymentMethod,subtotal:sub,discount,shippingCharge,total:Math.max(0,sub+shippingCharge-(state.couponDiscount||0))};try{let r=await fetch(API+"/orders",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+state.token},body:JSON.stringify(body)});let out=await r.json();if(!r.ok)throw Error(out.message);state.cart=[];state.activeCoupon=null;state.couponDiscount=0;save();toast("Order placed successfully!");go("account")}catch(err){toast(err.message)}}
async function loadOrders(){let el=document.getElementById("orders");try{let r=await fetch(API+"/orders/mine",{headers:{Authorization:"Bearer "+state.token}});let rows=await r.json();el.innerHTML=Array.isArray(rows)&&rows.length?`<div class="customer-orders">${rows.map(o=>`<article class="customer-order"><div class="customer-order-head"><div><b>Order #${String(o._id).slice(-7).toUpperCase()}</b><small>Placed ${new Date(o.createdAt).toLocaleDateString()}</small></div><span class="order-status status-${String(o.status).toLowerCase()}">${o.status}</span></div><div class="customer-order-items">${(o.items||[]).map(i=>`<div><img src="${i.image}" alt=""><span>${i.name}<small>Qty: ${i.quantity} · ${i.size||""} ${i.color||""}</small></span><b>${money(i.price*i.quantity)}</b></div>`).join("")}</div><div class="customer-order-total"><span>${o.shipping?.city||"Bangladesh"} · ${o.paymentMethod==="cod"?"Cash on Delivery":"Online Payment"}</span><b>Total ${money(o.total)}</b></div><div class="order-progress"><span class="${["Pending","Processing","Shipped","Delivered"].includes(o.status)?"done":""}">Order placed</span><span class="${["Processing","Shipped","Delivered"].includes(o.status)?"done":""}">Processing</span><span class="${["Shipped","Delivered"].includes(o.status)?"done":""}">Shipped</span><span class="${o.status==="Delivered"?"done":""}">Delivered</span></div></article>`).join("")}</div>`:"No orders yet. Start shopping to see your orders here."}catch(e){el.textContent="Could not load orders."}}
window.addEventListener("hashchange",render);document.documentElement.dataset.theme=localStorage.theme||"light";render();loadProducts();loadStorefront();
